from collections import Counter, defaultdict

def main():
	ht = defaultdict(list)
	cnt = Counter()
	n = int(input())
	for _ in range(n):
		s = input()
		(h, t) = (s[:2], s[1:])
		ht[h].append(t)
		cnt[h] += 1
		cnt[t] -= 1
	st = nd = flag = True
	for (t, i) in cnt.items():
		if i:
			if i == 1:
				if st:
					(st, h) = (False, t)
				else:
					break
			elif i == -1:
				if nd:
					nd = False
				else:
					break
			else:
				break
	else:
		flag = st != nd
	if flag:
		print('NO')
		return
	(stack, res) = ([h], [])
	while stack:
		m = stack[-1]
		if ht[m]:
			stack.append(ht[m].pop())
		else:
			del stack[-1]
			res.append(m[-1])
	if len(res) != n + 1:
		print('NO')
		return
	res.append(h[0])
	res.reverse()
	print('YES')
	print(''.join(res))
main()
